+                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.CORPORATE, "tecnosul"))));
+
+        Reservation reservation =
+                service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.CORPORATE, "TECNOSUL"));
+        assertEquals(new BigDecimal("219.91"), reservation.price().total());
+    }
+
+    @Test
+    void theCompanyCodeIsIgnoredByOtherPlans() {
+        Reservation reservation =
+                service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD, "TECNOSUL"));
+
+        assertEquals(new BigDecimal("249.90"), reservation.price().total());
+    }
+
+    @Test
+    void weekendPackageIsOnlyForFridayToSunday() {
+        // 2027-03-12 is a Friday
+        service.create(stay(101, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
+
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(102, "2027-03-11", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(102, "2027-03-12", "2027-03-15", 2, RatePlan.WEEKEND_PACKAGE))));
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(102, "2027-03-12", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
+    }
+
+    @Test
+    void weekendPackageGivesHalfBackOnCancellation() {
+        Reservation reservation = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
+        service.confirm(reservation.id());
+
+        assertEquals(new BigDecimal("410.00"), service.cancel(reservation.id()).refund());
+    }
+
+    @Test
+    void longStayNeedsSevenNightsAndGivesEverythingBackOnCancellation() {
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(101, "2027-03-01", "2027-03-07", 1, RatePlan.LONG_STAY))));
+
+        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 1, RatePlan.LONG_STAY));
+        service.confirm(reservation.id());
+
+        assertEquals(new BigDecimal("1574.37"), service.cancel(reservation.id()).refund());
+    }
